select case when d.budget >= 3834000 then 'high' when d.budget >= 1507000 then 'mid' else 'low' end as budget_bucket, sort_array(collect_set(e.level)) as level_list, sum(e.salary) as total_salary from employees e inner join departments d on e.dept_id = d.id where e.level = 'L4' group by case when d.budget >= 3834000 then 'high' when d.budget >= 1507000 then 'mid' else 'low' end order by budget_bucket
